+static char *
+value_type_tostr(dfvm_value_t *v, gboolean show_ftype)
+{
+	const char *s;
+
+	if (!v || !show_ftype)
+		return ws_strdup("");
+
+	switch (v->type) {
+		case HFINFO:
+		case RAW_HFINFO:
+			s = ftype_name(v->value.hfinfo->type);
+			break;
+		case FVALUE:
+			s = fvalue_type_name(v->value.fvalue);
+			break;
+		default:
+			return ws_strdup("");
+			break;
+	}
+	return ws_strdup_printf(" <%s>", s);
+}
